            d = list(digits)
            if sum(d)!=b: continue  # fail fast
            c = Counter(d)
            ok = True
            for i in range(b):
                if d[i] != c[i]:
                    ok = False
                    break
            if ok:
                return d
    return None

def fixpoint_selfdesc(b, MAX_ITER=100000):
    # Heuristic for larger b: try several seeds, do fixpoint iterations
    for seedval in [0,1,2,3]:
        d = [seedval]*b
        for rounds in range(MAX_ITER):
            c = Counter(d)
            newd = [c[i] for i in range(b)]
            if newd == d and sum(d)==b:
                return d
            d = newd
            if sum(d) > b:
                break
